# Fixed: Use output[r][c] not output[r,c]
def solve_task_fixed(grid):
    output = [row[:] for row in grid]
    visited = set()
    queue = []

    rows = len(grid)
    cols = len(grid[0])

    # Add edge 0s
    for c in range(cols):
        if grid[0][c] == 0:
            queue.append((0,c))
        if grid[rows-1][c] == 0:
            queue.append((rows-1,c))
    for r in range(rows):
        if grid[r][0] == 0:
            queue.append((r,0))
        if grid[r][cols-1] == 0:
            queue.append((r,cols-1))

    # Flood fill
    while queue:
        r, c = queue.pop(0)
        if (r,c) in visited:
            continue
        visited.add((r,c))
        output[r][c] = 2  # Fixed: output[r][c]

        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0 and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    output[nr][nc] = 2
                    queue.append((nr,nc))

    # Fill remaining 0s -> 3
    for r in range(rows):
        for c in range(cols):
            if output[r][c] == 0:
                output[r][c] = 3

    return output

result = solve_task_fixed(grid)
